    // with a line that can only come from this run.
    log::info!("=== {} {} starting ===", env!("CARGO_PKG_NAME"), env!("CARGO_PKG_VERSION"));
    log::info!("board: ESP32-035 LCD Panel (ESP32), 4 MB flash");
    // Backlight first, and note the level: this board switches the transistor on with a HIGH level.
    let backlight = Output::new(
        peripherals.GPIO27,
        Level::High,
        OutputConfig::default(),
    );

    let spi = Spi::new(
        peripherals.SPI2,
        // 3.5" ST7796 320x480: 24000000 Hz. Lower this first if the image is unstable.
        panel_clock(),
    )
    .expect("SPI configuration")
        .with_sck(peripherals.GPIO14)
        .with_mosi(peripherals.GPIO13)
        .with_miso(peripherals.GPIO12);

    // esp-hal's Spi is a *bus*; mipidsi wants a SpiDevice, which is that bus plus its own CS pin.
    // embedded-hal-bus is the crate that joins the two (the recipe esp-hal's own examples use).
    let cs = Output::new(peripherals.GPIO15, Level::Low, OutputConfig::default());
    let spi = ExclusiveDevice::new(spi, cs, Delay::new()).expect("SPI device");

